def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if not points:
        return out
    rows = sorted(r for r, _ in points)
    cols = sorted(c for _, c in points)
    median_row = rows[len(rows) // 2]
    median_col = cols[len(cols) // 2]
    h_cost = max(c for _, c in points) - min(c for _, c in points) + sum(abs(r - median_row) for r, _ in points)
    v_cost = max(r for r, _ in points) - min(r for r, _ in points) + sum(abs(c - median_col) for _, c in points)
    if h_cost <= v_cost:
        for c in range(min(c for _, c in points), max(c for _, c in points) + 1):
            if out[median_row][c] == 0:
                out[median_row][c] = 3
        for r, c in points:
            for rr in range(min(r, median_row), max(r, median_row) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        for r in range(min(r for r, _ in points), max(r for r, _ in points) + 1):
            if out[r][median_col] == 0:
                out[r][median_col] = 3
        for r, c in points:
            for cc in range(min(c, median_col), max(c, median_col) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    return out
